    syntaxExample: 'import { useState } from "react";\n\nfunction Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <div>\n      <p>Count: {count}</p>\n      <button onClick={() => setCount(count + 1)}>+</button>\n      <button onClick={() => setCount(count - 1)}>-</button>\n      <button onClick={() => setCount(0)}>Reset</button>\n    </div>\n  );\n}',
    visualExplanation: 'Component lifecycle:\n  1. Initial: count = 0, renders "Count: 0"\n  2. User clicks [+]: setCount(1)\n  3. React re-renders: "Count: 1"\n  4. Only the changed text updates in the real DOM',
