    concept: 'useEffect runs after React renders to the screen. Use it for side effects: fetching data, setting up subscriptions, timers, or manually modifying the DOM. The dependency array controls when the effect re-runs. Return a cleanup function to prevent memory leaks.',
    syntaxExample: 'import { useState, useEffect } from "react";\n\nfunction UserProfile({ userId }) {\n  const [user, setUser] = useState(null);\n  const [loading, setLoading] = useState(true);\n\n  useEffect(() => {\n    setLoading(true);\n    fetch("/api/users/" + userId)\n      .then(res => res.json())\n      .then(data => {\n        setUser(data);\n        setLoading(false);\n      });\n\n    return () => { /* cleanup */ };\n  }, [userId]);\n\n  if (loading) return <Spinner />;\n  return <div>{user.name}</div>;\n}',
