    description: 'Build forms where React state controls inputs (controlled components).',
    concept: 'In controlled components, React state is the single source of truth for form inputs. The input value is controlled by state, and onChange updates that state. This gives you full control over validation, formatting, and submission. Every keystroke updates state and re-renders.',
    syntaxExample: 'function LoginForm() {\n  const [form, setForm] = useState({ email: "", password: "" });\n\n  function handleChange(e) {\n    const { name, value } = e.target;\n    setForm(prev => ({ ...prev, [name]: value }));\n  }\n\n  function handleSubmit(e) {\n    e.preventDefault();\n  }\n\n  return (\n    <form onSubmit={handleSubmit}>\n      <input name="email" value={form.email} onChange={handleChange} />\n      <input type="password" name="password" value={form.password} onChange={handleChange} />\n      <button type="submit">Login</button>\n    </form>\n  );\n}',
